  font-size: 17px;
  line-height: 1.3;
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.section {
  padding: var(--space-7) 0 0;
}

.section-title {
  margin-bottom: var(--space-5);
}

.page-head {
